export default function configure({ spreadsheetId, sheetName }) {
  if (
    !/^[\w-]+$/.test(spreadsheetId) ||
    spreadsheetId === "YOUR_SPREADSHEET_ID" ||
    !sheetName.trim()
  ) {
    throw new Error("Set the spreadsheet ID and sheet tab before running");
  }
  return { spreadsheetId, tab: "'" + sheetName.replace(/'/g, "''") + "'" };
}

