export default function prepare({ rows, tab }) {
  const header = rows[0] ?? [];
  const column = (name) => {
    const index = header.indexOf(name);
    if (index === -1 || index !== header.lastIndexOf(name)) {
      throw new Error("Expected one header named " + name);
    }
    return index;
  };
  const urlColumn = column("Linkedin_URL_Company");
  const scoreColumn = column("ICP_Score_Company");
  let letters = "";
  for (let n = scoreColumn + 1; n > 0; n = Math.floor((n - 1) / 26)) {
    letters = String.fromCharCode(65 + ((n - 1) % 26)) + letters;
  }
  const companies = rows.slice(1).flatMap((row, index) => {
    const original = String(row[urlColumn] ?? "");
    if (!original.trim()) return [];
    const match =
      /^https:\/\/(?:[a-z]{2,3}\.|www\.)?linkedin\.com\/company\/([\w%-]+)(?:\/(?:about|posts|people|jobs|life))?\/?(?:[?#].*)?$/i.exec(
        original.trim(),
      );
    if (!match) throw new Error("Expected a LinkedIn company URL on row " + (index + 2));
    return [
      {
        row: index + 2,
        original,
        url: "https://www.linkedin.com/company/" + match[1] + "/",
        range: tab + "!" + letters + (index + 2),
      },
    ];
  });
  return { companies, urlColumn, scoreColumn };
}

