export default function next({ companies, completed }) {
  const current = companies[completed?.length ?? 0] ?? null;
  return {
    current,
    more: current !== null,
    hasScores: (completed?.length ?? 0) > 0,
    scored: completed ?? [],
    profileRequest: { query: { url: current?.url ?? "" } },
    postsRequest: { query: { url: current?.url ?? "", start: 0, sort_by: "recent" } },
  };
}

