export default function evidence({ profile, posts, current }) {
  for (const item of [profile, posts]) {
    if (item.code !== 200 || item.data === null || typeof item.data !== "object") {
      throw new Error("TikHub did not return company evidence");
    }
  }
  // Bound prompt size without changing the order of recent posts.
  const excerpt = (data, limit) => JSON.stringify(data).slice(0, limit);
  return {
    url: current.url,
    profileText: excerpt(profile.data, 18000),
    postsText: excerpt(posts.data, 18000),
  };
}

