export default function score({ assessment, current, previous }) {
  const points = {
    focus: { low: 5, medium: 10, high: 25 },
    technical: { basic: 5, intermediate: 15, advanced: 25, expert: 35 },
    size: { small: 5, medium: 25, large: 30 },
  };
  const { aiFocus, technicalLevel, sizeBracket, automationAgency, usOrEurope } = assessment;
  const scores = [
    points.focus[aiFocus],
    points.technical[technicalLevel],
    points.size[sizeBracket],
  ];
  if (!scores.every(Number.isInteger)) {
    throw new Error("Insufficient evidence to score the company on row " + current.row);
  }
  const total =
    scores[0] + scores[1] + scores[2] + (automationAgency ? 20 : 0) + (usOrEurope ? 10 : 0);
  return { completed: [...(previous ?? []), { range: current.range, values: [[total]] }] };
}

