export default function verify({ rows, companies, urlColumn, scoreColumn, completed }) {
  const header = rows[0] ?? [];
  if (header[urlColumn] !== "Linkedin_URL_Company" || header[scoreColumn] !== "ICP_Score_Company") {
    throw new Error("The company sheet headers changed during scoring");
  }
  if (companies.some(({ row, original }) => rows[row - 1]?.[urlColumn] !== original)) {
    throw new Error("A company URL or its row position changed during scoring");
  }
  if (
    completed.length !== companies.length ||
    completed.some(({ range }, i) => range !== companies[i].range)
  ) {
    throw new Error("Score and company row association is incomplete");
  }
  return { data: completed };
}

