export default function confirm({ totalUpdatedCells, responses, data }) {
  if (
    totalUpdatedCells !== data.length ||
    responses.length !== data.length ||
    responses.some(
      (response, i) =>
        response.updatedCells !== 1 ||
        response.updatedData?.values?.[0]?.[0] !== data[i].values[0][0],
    )
  )
    throw new Error("Check Google Sheets before retrying the score update");
  return { updatedCompanies: totalUpdatedCells };
}
